'use strict';
const C=window.OCCCI_SUPABASE_CONFIG,SESSION_KEY='occci.supabase.session.v1';
const S={session:null,role:'Member',assignment:null,page:'Home',authMode:'login',branches:[],profiles:[],financials:[],requests:[],content:[],audit:[],team:[],applications:[],me:null,scope:'all',search:'',pageNumber:1,error:'',busy:false,photoUrl:'',directoryDistrict:null};
const memberNav=[['Home','home'],['Accounts','wallet'],['Community','megaphone'],['Activity','clock'],['Profile','user']];
const cmsNav=[['Overview','grid'],['Members','users'],['Approvals','shield'],['Financial sync','wallet'],['Content','megaphone'],['Activity','clock'],['Team','users'],['Branches','location']];
const $=id=>document.getElementById(id);const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const bn=id=>S.branches.find(b=>b.id===id)?.name||'Unassigned';const isStaff=()=>S.role!=='Member';
function storeSession(s){S.session=s;try{s?localStorage.setItem(SESSION_KEY,JSON.stringify(s)):localStorage.removeItem(SESSION_KEY);}catch{}}
async function ensureSession(){if(!S.session)throw Error('Sign in to continue.');if(!S.session.expires_at||S.session.expires_at<Date.now()/1000+60){try{const d=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',data:{refresh_token:S.session.refresh_token},auth:false});storeSession({...d,expires_at:Date.now()/1000+d.expires_in});}catch(err){storeSession(null);clearData();throw err;}}}
async function api(path,{method='GET',data,auth=true,headers={},raw=false}={}){if(auth)await ensureSession();const h={apikey:C.publishableKey,...headers};if(auth)h.Authorization='Bearer '+S.session.access_token;if(!raw)h['Content-Type']='application/json';const res=await fetch(C.url+path,{method,headers:h,body:data===undefined?undefined:raw?data:JSON.stringify(data),cache:'no-store'});let out=null;try{out=await res.json();}catch{}if(!res.ok){if(['PGRST205','PGRST202','42703'].includes(out?.code))throw Error('Workflow database setup is pending. Run the OCCCI workflow SQL in Supabase.');if(out?.code==='23505')throw Error('This account number is already assigned. Use the official unique number for this member.');throw Error(out?.msg||out?.message||out?.error_description||out?.error||'Connection failed. Please try again.');}return out;}
async function allRows(path){const result=[];for(let offset=0;;offset+=500){const page=await api(path+(path.includes('?')?'&':'?')+'limit=500&offset='+offset);result.push(...page);if(page.length<500)return result;}}
const rpc=(name,data)=>api('/rest/v1/rpc/'+name,{method:'POST',data});
function clearData(){for(const key of ['profiles','financials','requests','content','audit','team','applications'])S[key]=[];S.me=null;S.role='Member';S.assignment=null;S.photoUrl='';}
async function loadBranches(){S.branches=await api('/rest/v1/occci_branches?select=id,name,district,active&order=district,name',{auth:false});}
async function reload(){S.busy=true;S.error='';render();try{await ensureSession();const user=await api('/auth/v1/user');S.session.user=user;S.assignment=(await api('/rest/v1/occci_staff_assignments?user_id=eq.'+user.id+'&select=*'))[0]||null;S.role=S.assignment?.role||'Member';const result=await Promise.all([
 allRows('/rest/v1/occci_profiles?select=*&archived_at=is.null&order=created_at.desc,id'),allRows('/rest/v1/occci_financials?select=*&order=member_id'),allRows('/rest/v1/occci_change_requests?select=*&order=created_at.desc,id'),allRows('/rest/v1/occci_content?select=*&archived_at=is.null&order=updated_at.desc,id'),loadActivity(),allRows('/rest/v1/occci_staff_assignments?select=*&order=user_id'),allRows('/rest/v1/occci_staff_applications?select=*&order=created_at.desc,user_id')]);[S.profiles,S.financials,S.requests,S.content,S.audit,S.team,S.applications]=result;S.me=S.profiles.find(p=>p.id===user.id)||null;if(!S.me)throw Error('Your profile is missing or archived. Contact the cooperative administrator.');if(S.scope!=='all'&&!allowedBranches().some(b=>b.id===S.scope))S.scope='all';S.photoUrl='';if(S.me.photo_path){try{S.photoUrl=await signedUrl('occci-avatars',S.me.photo_path);}catch{}}}catch(err){S.error=err.message;}finally{S.busy=false;render();}}
function allowedBranches(){return S.branches.filter(b=>S.role==='Admin'||(S.role==='DM'?b.district===S.assignment?.district:b.id===S.assignment?.branch_id));}
function scoped(rows){return rows.filter(r=>S.scope==='all'||(r.branch_id||S.profiles.find(p=>p.id===r.member_id)?.branch_id)===S.scope);}
function branchOptions(selected,all=false,restricted=false){const rows=restricted?allowedBranches():S.branches.filter(b=>b.active);return (all?`<option value="all">All assigned branches</option>`:'')+[...new Set(rows.map(b=>b.district))].sort().map(d=>`<optgroup label="District ${d}">${rows.filter(b=>b.district===d).map(b=>`<option value="${e(b.id)}" ${selected===b.id?'selected':''}>OCCCI ${e(b.name)} Branch</option>`).join('')}</optgroup>`).join('');}
function currentNav(){return isStaff()?cmsNav:S.me?.registration_kind==='Staff'?memberNav.filter(([n])=>n!=='Accounts'):memberNav;}
function go(page){S.page=page;S.pageNumber=1;closeModal();render();window.scrollTo({top:0});}
function render(){document.title='OCCCI Member Connect';const nav=currentNav();$('sidebar').innerHTML=`<div class="brand">${logo()}<div><strong>OCCCI</strong><small>${isStaff()?e(S.role)+' workspace':'Member Connect'}</small></div></div><nav class="nav-section">${S.session?nav.map(([n,i])=>button(n,`go('${n}')`,'nav-item '+(S.page===n?'active':''),i)).join(''):''}</nav><div class="sidebar-end"><b>Metro Ormoc Community</b><p>Multi-Purpose Cooperative</p>${S.session?button('Sign out','signOut()','','switch'):''}</div>`;
 $('topbar').innerHTML=`<div class="mobile-brand">${logo()}<div><strong>OCCCI</strong><small>Metro Ormoc Community<br>Multi-Purpose Cooperative</small></div></div><div class="desktop-heading"><strong>Metro Ormoc Community Multi-Purpose Cooperative</strong><span>Member Connect</span></div><div class="top-actions">${S.session?`${button('','reload()','icon-btn','switch')}<button class="profile-button" onclick="go('Profile')" aria-label="Your profile"><span class="avatar">${S.photoUrl?`<img src="${e(S.photoUrl)}" alt="Your profile" style="width:100%;height:100%;object-fit:cover">`:avatarArt(S.me?.avatar||'lady')}</span><span class="profile-name"><b>${e(S.me?.full_name||'Member')}</b><small>${e(S.role)} · ${e(bn(S.me?.branch_id))}</small></span></button>${button('','openMenu()','icon-btn menu-button','menu')}`:''}</div>`;
 $('demoBar').innerHTML=S.session?`<span class="demo-label">${e(S.role.toUpperCase())}</span><span>${isStaff()?'Authorized cooperative workspace':S.me?.registration_kind==='Staff'?'Staff application '+e(S.applications.find(a=>a.user_id===S.me.id)?.status||'Pending'):S.me?.membership_status==='Active'?'Verified membership':'Membership verification pending'}</span>${isStaff()?`<select aria-label="Branch workspace" onchange="S.scope=this.value;S.pageNumber=1;render()">${branchOptions(S.scope,true,true)}</select>`:''}`:'<span class="demo-label">MEMBER CONNECT</span><span>Your cooperative, connected.</span>';
 $('bottomnav').innerHTML=S.session?(isStaff()?[['Overview','grid'],['Members','users'],['Approvals','shield'],['Activity','clock'],['More','menu']]:currentNav()).map(([n,i])=>button(`${icon(i)}<span>${n}</span>`,n==='More'?'openMenu()':`go('${n}')`,n===S.page?'active':'')).join(''):'';
 $('bottomnav').style.display=S.session?'':'none';let html;if(!S.session)html=authView();else if(S.busy&&!S.me)html=empty('Loading your workspace','Connecting to cooperative records.');else if(S.error)html=`<div class="banner"><div><h2>Workspace needs attention</h2><p>${e(S.error)}</p></div>${button('Retry','reload()','primary')}</div>`;else if(S.me?.onboarding_complete===false)html=onboardingView();else html=isStaff()?cmsView():memberView();$('main').innerHTML=html;document.querySelectorAll('select[aria-label="Branch workspace"]').forEach(n=>n.value=S.scope);}
function openModal(title,body){$('modalContent').innerHTML=`<div class="dialog-head"><h2 id="dialogTitle">${e(title)}</h2>${button('','closeModal()','icon-btn','close')}</div><div class="dialog-body"><p id="actionMessage" role="alert" aria-live="polite" class="form-error"></p>${body}</div>`;if(!$('modal').open)$('modal').showModal();}
function closeModal(){if($('modal').open)$('modal').close();}function toast(text){$('toast').textContent=text;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,4000);}
function openMenu(){openModal('Your workspace',`<div class="mobile-menu">${currentNav().map(([n,i])=>button(n,`go('${n}')`,'',i)).join('')}</div>${button('My profile',"go('Profile')",'outline','user')}${button('Sign out','signOut()','secondary','switch')}`);}
function field(label,name,value='',type='text',required=true){return `<label>${label}<input name="${name}" type="${type}" value="${e(value)}" ${required?'required':''} ${type==='number'?'min="0" step="0.01"':''} maxlength="${['first_name','last_name','middle_name'].includes(name)?50:name==='contact_number'?30:name==='address'?500:150}"></label>`;}
function authView(){const reg=S.authMode==='register';return `<section class="card auth-card"><div class="card-head"><div><h1>${reg?'Become connected':'Welcome to OCCCI'}</h1><p class="muted">${reg?'Create an account for membership or staff verification.':'Sign in to your member or staff workspace.'}</p></div></div><div class="tabs">${button('Sign in',"S.authMode='login';render()",!reg?'active':'')}${button('Register',"S.authMode='register';render()",reg?'active':'')}</div>${S.error?`<p role="alert" class="form-error">${e(S.error)}</p>`:''}<button type="button" class="google-signin outline" onclick="googleSignIn(this)"><span class="google-mark" aria-hidden="true">G</span>Continue with Google</button><p class="auth-divider">or use email</p><form onsubmit="event.preventDefault();submitAuth(this)"><div class="form-grid">${reg?`${signupKindPicker()}${field('Last name','last_name')}${field('First name','first_name')}${field('Middle name (optional)','middle_name','','text',false)}${field('Contact number','contact_number','','tel')}<label class="full">Complete address<textarea name="address" maxlength="500" required autocomplete="street-address"></textarea></label><label>District<select name="district" onchange="registrationBranches(this.value)" required>${[...new Set(S.branches.filter(b=>b.active).map(b=>b.district))].sort().map(d=>`<option value="${d}">District ${d}</option>`).join('')}</select></label><label>Branch<select id="registerBranch" name="branch_id" required>${registrationOptions(S.branches.find(b=>b.active)?.district)}</select></label>${avatarPicker()}<label class="full">Profile photo (optional)<input type="file" name="photo" accept="image/*"><span class="hint">Use an avatar if your iPhone or iPad cannot upload the photo. JPG/PNG photos are supported; photos from other formats will be converted when possible.</span></label>`:''}${field('Email','email','','email')}<label>Password<input name="password" type="password" minlength="8" autocomplete="${reg?'new-password':'current-password'}" required></label></div><p class="smalltext">${reg?'Confirm your email, then sign in. Members need branch verification. OCCCI Staff applicants need cooperative Admin approval for their requested position.':'Your access is determined by your cooperative assignment.'}</p><button type="submit" class="primary">${reg?'Create account':'Sign in'}</button><p id="authMessage" role="status" aria-live="polite"></p></form></section>`;}
function signupKindPicker(){return `<fieldset class="signup-kind full"><legend>How would you like to sign up?</legend><div class="signup-options"><label><input type="radio" name="registration_kind" value="Member" checked onchange="staffSignupFields(false)"><span class="iconbox">${icon('user')}</span><span><strong>Cooperative Member</strong><small>Membership and personal accounts</small></span></label><label><input type="radio" name="registration_kind" value="Staff" onchange="staffSignupFields(true)"><span class="iconbox">${icon('shield')}</span><span><strong>OCCCI Staff</strong><small>Apply for DM, BM or Staff access</small></span></label></div></fieldset><label class="full" id="staffRoleField" hidden>Requested position<select name="requested_role" disabled><option value="Staff">Staff</option><option value="BM">Branch Manager (BM)</option><option value="DM">District Manager (DM)</option></select><span class="hint">Your selected district and branch define the requested assignment. Admin reviews your application before CMS access is granted.</span></label>`;}
function staffSignupFields(staff){const field=$('staffRoleField');field.hidden=!staff;const select=field.querySelector('select');select.disabled=!staff;select.required=staff;}
function registrationOptions(d){return S.branches.filter(b=>b.active&&b.district===Number(d)).map(b=>`<option value="${e(b.id)}">${e(b.name)}</option>`).join('');}function registrationBranches(d){$('registerBranch').innerHTML=registrationOptions(d);}
async function normalizePhoto(file){if(file.size>5*1024*1024)throw Error('Photo is larger than 5 MB. Choose a smaller photo or use an avatar.');return new Promise((resolve,reject)=>{const url=URL.createObjectURL(file),img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');const scale=Math.min(1,900/Math.max(img.width,img.height));canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);canvas.toBlob(b=>b?resolve(b):reject(Error('Use a temporary avatar; this photo cannot be converted.')),'image/jpeg',.85);};img.onerror=()=>{URL.revokeObjectURL(url);reject(Error('Your device cannot open this photo. You can continue with a temporary avatar.'));};img.src=url;});}
let pendingPhoto=null;
async function requireStaffSignupSchema(){const response=await fetch(C.url+'/rest/v1/occci_staff_applications?select=user_id&limit=0',{headers:{apikey:C.publishableKey},cache:'no-store'});let result={};try{result=await response.json();}catch{}if(response.ok||result.code==='42501')return;throw Error(['PGRST205','PGRST204','42P01'].includes(result.code)?'OCCCI Staff signup is awaiting database activation. Run the staff-signup migration in Supabase before applying.':'Unable to verify staff signup availability. Please try again.');}
async function submitAuth(form){const btn=form.querySelector('button[type=submit],button:not([type])');const buttonLabel=btn?.textContent;if(btn)btn.disabled=true;const f=new FormData(form);try{if(S.authMode==='register'){const branch=S.branches.find(b=>b.id===f.get('branch_id')&&b.district===Number(f.get('district'))&&b.active);if(!branch)throw Error('Choose a branch in your district.');const data=Object.fromEntries(['last_name','first_name','middle_name','contact_number','address','avatar'].map(k=>[k,String(f.get(k)||'').trim()]));if(data.contact_number.length<7||data.address.length<5)throw Error('Enter a complete address and contact number.');data.branch_id=branch.id;data.district=branch.district;data.registration_kind=f.get('registration_kind')||'Member';if(data.registration_kind==='Staff'){await requireStaffSignupSchema();data.requested_role=f.get('requested_role');if(!['DM','BM','Staff'].includes(data.requested_role))throw Error('Select your requested staff position.');}pendingPhoto=null;const file=f.get('photo');if(file?.size){try{pendingPhoto=await normalizePhoto(file);}catch(err){$('authMessage').textContent=err.message+' Registering with your selected avatar.';}}const result=await api('/auth/v1/signup',{method:'POST',auth:false,data:{email:f.get('email'),password:f.get('password'),data}});if(result.access_token){storeSession({...result,expires_at:Date.now()/1000+result.expires_in});await reload();if(pendingPhoto)await uploadPhotoBlob(pendingPhoto);}else{$('authMessage').textContent='Check your email to confirm your account, then return to sign in. You can upload your photo after signing in.';form.reset();staffSignupFields(false);}}
 else{const result=await api('/auth/v1/token?grant_type=password',{method:'POST',auth:false,data:{email:f.get('email'),password:f.get('password')}});storeSession({...result,expires_at:Date.now()/1000+result.expires_in});S.page='Home';await reload();if(isStaff()){S.page='Overview';render();}if(pendingPhoto){try{await uploadPhotoBlob(pendingPhoto);}catch(err){toast(err.message);}pendingPhoto=null;}}}catch(err){const node=$('authMessage');if(node)node.textContent=err.message;else{S.error=err.message;render();}}finally{btn.disabled=false;}}
async function signOut(){try{await api('/auth/v1/logout',{method:'POST'});}catch{}storeSession(null);clearData();S.error='';S.page='Home';S.scope='all';closeModal();render();}
async function upload(bucket,file){const extension=bucket==='occci-avatars'?(file.type==='image/png'?'png':'jpg'):(file.name?.split('.').pop()?.replace(/[^a-zA-Z0-9]/g,'').slice(0,16)||'bin');const path=S.session.user.id+'/'+crypto.randomUUID()+'.'+extension;await api('/storage/v1/object/'+bucket+'/'+path,{method:'POST',data:file,raw:true,headers:{'Content-Type':file.type||'application/octet-stream'}});return path;}
async function signedUrl(bucket,path){const result=await api('/storage/v1/object/sign/'+bucket+'/'+path,{method:'POST',data:{expiresIn:300}});return C.url+'/storage/v1'+result.signedURL;}
async function uploadPhotoBlob(blob){const path=await upload('occci-avatars',blob);await rpc('occci_set_photo',{photo:path});pendingPhoto=null;await reload();toast('Profile photo updated.');}
async function changePhoto(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const file=new FormData(form).get('photo');await uploadPhotoBlob(await normalizePhoto(file));}catch(err){$('actionMessage').textContent=err.message;}finally{btn.disabled=false;}}
function profileView(){const p=S.me;return heading('My profile','Your cooperative member details.')+`<section class="card"><div class="profile-summary"><span class="avatar">${S.photoUrl?`<img src="${e(S.photoUrl)}" alt="Profile photo" style="width:100%;height:100%;object-fit:cover">`:avatarArt(p.avatar)}</span><div><h2>${e(p.full_name)}</h2><p>${e(p.membership_status)} · ${e(S.role)}</p></div></div><dl class="details-list">${detail('Account number',e(p.account_number||'Awaiting approval'))}${detail('District','District '+S.branches.find(b=>b.id===p.branch_id)?.district)}${detail('Branch',e(bn(p.branch_id)))}${detail('Email',e(S.session.user.email))}${detail('Contact',e(p.contact_number||'Not yet recorded'))}${detail('Address',e(p.address||'Not yet recorded'))}</dl>${button('Upload profile photo','photoDialog()','outline','user')}<p class="smalltext">To correct member information, contact your branch staff. Every approved correction is recorded in your activity log.</p></section>`;}
function photoDialog(){openModal('Profile photo',`<form onsubmit="event.preventDefault();changePhoto(this)"><label>Photo<input type="file" name="photo" accept="image/*" required></label><p class="hint">If your device cannot upload a photo, your temporary avatar stays in place.</p><button class="primary" type="submit">Upload photo</button></form>`);}
function memberView(){if(S.me.registration_kind==='Staff'&&['Home','Accounts'].includes(S.page))return staffApplicantView();if(S.page==='Profile')return profileView();if(S.page==='Activity')return auditView(S.audit.filter(a=>a.member_id===S.me.id));if(S.page==='Community')return contentView(false);const f=S.financials.find(f=>f.member_id===S.me.id);return heading(S.page==='Accounts'?'My accounts':'Welcome, '+e(S.me.first_name||S.me.full_name),`${e(bn(S.me.branch_id))} branch · ${e(S.me.account_number||'Account number pending')}`)+`<div class="grid equal"><section class="card balance"><p>Total active savings</p><div class="amount">${f?money(f.savings):'Awaiting verified records'}</div><p>${f?'Verified as of '+e(f.as_of):'Your branch will synchronize your actual documents after approval.'}</p></section><section class="card"><h2>Loan overview</h2>${f?`<dl class="details-list">${detail('Outstanding balance',money(f.loan_balance))}${detail('Status',e(f.loan_status))}${detail('Annual interest',e(f.annual_interest)+'%')}${detail('Source reference',e(f.source_reference))}</dl>`:'<p class="muted">No verified loan record has been synchronized.</p>'}</section></div><section class="card spacer"><h2>Payment schedule</h2>${f?scheduleView(f.schedule):empty('No schedule yet','Only approved document records appear here.')}</section>${S.page==='Home'?'<section class="spacer">'+contentView(false,false)+'</section>':''}`;}
function staffApplicantView(){const a=S.applications.find(a=>a.user_id===S.me.id);return heading('Your OCCCI Staff application','CMS access becomes available after cooperative Admin approval.')+`<section class="card"><div class="card-head"><h2>${e(S.me.full_name)}</h2>${statusPill(a?.status||'Awaiting review')}</div><dl class="details-list">${detail('Requested position',e(a?.requested_role||'Not recorded'))}${detail('District',a?'District '+a.district:'Not recorded')}${detail('Branch',e(bn(a?.branch_id||S.me.branch_id)))}</dl><p>${e(a?.review_note||'Confirm your email. The cooperative Admin will verify your position and assignment.')}</p>${button('Refresh status','reload()','primary')}${button('My profile',"go('Profile')",'outline')}</section>`;}
function scheduleView(rows){return rows?.length?`<div class="schedule-list">${rows.map(x=>`<div class="transaction-row"><div><h3>${e(x.date)}</h3><small>${e(x.status||'Scheduled')}</small></div><strong>${money(x.amount)}</strong></div>`).join('')}</div>`:empty('No payment schedule','A schedule will appear when your branch syncs it.');}
function metric(label,value,sub){return `<section class="card admin-metric"><p class="eyebrow">${label}</p><div class="big-number">${value}</div><p class="smalltext">${sub}</p></section>`;}
function cmsView(){if(S.page==='Profile')return profileView();if(S.page==='Members')return membersView();if(S.page==='Approvals')return approvalsView();if(S.page==='Financial sync')return financialView();if(S.page==='Content')return contentView(true);if(S.page==='Activity')return auditView(S.audit);if(S.page==='Team')return teamView();if(S.page==='Branches')return branchesView();const profiles=scoped(S.profiles).filter(p=>p.registration_kind!=='Staff'),requests=scoped(S.requests);return heading('Cooperative workspace',`${e(S.role)} · ${S.role==='DM'?'District '+S.assignment.district:S.role==='Admin'?'All districts':e(bn(S.assignment.branch_id))+' branch'}`)+`<div class="grid four">${metric('Members',profiles.filter(p=>p.membership_status==='Active').length,'Approved memberships')}${metric('New registrations',profiles.filter(p=>p.membership_status==='Pending verification').length,'Awaiting account number')}${metric('Edit requests',requests.filter(q=>q.kind==='Profile edit'&&['Pending','BM approved'].includes(q.status)).length,'BM approval workflow')}${metric('Financial sync',requests.filter(q=>q.kind==='Financial sync'&&['Pending','DM approved'].includes(q.status)).length,'DM then Admin review')}</div><section class="card spacer"><h2>Priority work</h2><div class="priority-actions">${S.role==='Admin'?button('Approve staff applications',"go('Team')",'gold','shield'):''}${button('Approve new members',"go('Members')",'primary','users')}${button('Review staff edits',"go('Approvals')",'outline','shield')}${button('Review actual balances',"go('Financial sync')",'outline','wallet')}</div><p class="smalltext">Membership, edits, document submissions and approvals are recorded in the CMS and member activity logs.</p></section>`;}
function normalized(text){return String(text||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');}
function editDistance(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i),older=null;for(let i=1;i<=a.length;i++){const row=[i];for(let j=1;j<=b.length;j++){row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]!==b[j-1]));if(i>1&&j>1&&a[i-1]===b[j-2]&&a[i-2]===b[j-1])row[j]=Math.min(row[j],older[j-2]+1);}older=prev;prev=row;}return prev[b.length];}
function memberMatches(p,query){const q=String(query).trim();if(!q)return true;if(p.account_number?.toLowerCase()===q.toLowerCase())return true;const key=normalized(q),name=normalized(p.full_name);if(name.includes(key))return true;if(key.length<3)return false;const words=String(p.full_name).split(/\s+/).map(normalized);return words.some(w=>editDistance(w,key)<=Math.max(1,Math.floor(key.length/4)))||[...key].every((ch,index,all)=>{let pos=-1;for(const c of all.slice(0,index+1)){pos=name.indexOf(c,pos+1);if(pos<0)return false;}return true;});}
function membersView(){const rows=scoped(S.profiles).filter(p=>p.registration_kind!=='Staff').filter(p=>memberMatches(p,S.search));const size=12;S.pageNumber=Math.min(S.pageNumber,Math.max(1,Math.ceil(rows.length/size)));const show=rows.slice((S.pageNumber-1)*size,S.pageNumber*size);return heading('Members by branch','Search an exact account number, part of a name, or a similar spelling.')+`<section class="card"><label class="search">${icon('search')}<input type="search" placeholder="Account number or member name" value="${e(S.search)}" oninput="S.search=this.value;S.pageNumber=1;refreshMemberList()"></label><div id="memberList">${memberList(show,rows.length)}</div></section>`;}
function refreshMemberList(){const rows=scoped(S.profiles).filter(p=>p.registration_kind!=='Staff').filter(p=>memberMatches(p,S.search));$('memberList').innerHTML=memberList(rows.slice(0,12),rows.length);}
function memberList(rows,total){return `<p class="directory-count">${total} matching members</p>${[...new Set(rows.map(p=>p.branch_id))].map(branch=>`<section class="member-branch-group"><h3>${e(bn(branch))} branch</h3><div class="member-cards">${rows.filter(p=>p.branch_id===branch).map(p=>`<article class="member-directory-card"><span class="avatar">${avatarArt(p.avatar)}</span><div class="member-card-info"><h3>${e(p.full_name)}</h3><p>${e(p.account_number||'No account number assigned')}</p><small>${e(p.membership_status)}</small></div>${button('View',`memberDialog('${p.id}')`,'small secondary')}</article>`).join('')}</div></section>`).join('')||empty('No matching members','Choose a branch or try fewer characters.')}<div class="pagination"><span>Page ${S.pageNumber} of ${Math.max(1,Math.ceil(total/12))}</span><div class="flex">${button('Previous',"S.pageNumber=Math.max(1,S.pageNumber-1);render()",'outline small')}${button('Next',"S.pageNumber++;render()",'outline small')}</div></div>`;}
function memberDialog(id){const p=S.profiles.find(p=>p.id===id);if(!p)return;openModal(p.full_name,`<dl class="details-list">${detail('Account',e(p.account_number||'Pending'))}${detail('Branch',e(bn(p.branch_id)))}${detail('Contact',e(p.contact_number||'Not yet recorded'))}${detail('Address',e(p.address||'Not yet recorded'))}${detail('Status',e(p.membership_status))}</dl><div class="priority-actions">${p.membership_status==='Pending verification'&&['Admin','DM','BM','Staff'].includes(S.role)?button('Approve membership',`membershipDialog('${id}')`,'primary','check'):''}${button(S.role==='Staff'?'Request information edit':'Edit member information',S.role==='Staff'?`editPermissionDialog('${id}')`:`editDialog('${id}')`,'outline','edit')}${button('Assign / update ID number',`accountDialog('${id}')`,'outline','user')}${button('Submit actual balances',`syncDialog('${id}')`,'outline','wallet')}${S.role==='Admin'?button('Archive member',`removeDialog('Member','${id}')`,'danger'):''}</div><h3 class="spacer">Member activity</h3>${auditRows(S.audit.filter(a=>a.member_id===id).slice(0,10))}`);}
function membershipDialog(id){openModal('Approve membership',`<form onsubmit="event.preventDefault();handleCmsAction(this,'membership','${id}')"><label>Official ID / account number<input name="account" value="${e(S.profiles.find(p=>p.id===id)?.account_number||'')}" maxlength="40" pattern="[A-Za-z0-9][A-Za-z0-9/\\-]{2,39}" required></label><label class="spacer">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><p class="smalltext">Use the account number verified by your branch. Duplicate account numbers are rejected.</p><button class="primary" type="submit">Approve and assign account</button></form>`);}
function editDialog(id,requestId=''){if(S.role==='Staff'&&!requestId)return editPermissionDialog(id);const p=S.profiles.find(p=>p.id===id);openModal('Member information edit',`<form onsubmit="event.preventDefault();handleCmsAction(this,'edit','${id}','${requestId}')"><div class="form-grid">${field('Last name','last_name',p.last_name)}${field('First name','first_name',p.first_name)}${field('Middle name','middle_name',p.middle_name,'text',false)}${field('Contact number','contact_number',p.contact_number,'tel')}<label class="full">Complete address<textarea name="address" maxlength="500" required>${e(p.address)}</textarea></label><label>Status<select name="membership_status">${['Active','Suspended','Pending verification'].map(v=>`<option ${v===p.membership_status?'selected':''}>${v}</option>`).join('')}</select></label>${avatarPicker(p.avatar)}<label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label></div><p class="smalltext">${['DM','BM','Admin'].includes(S.role)?'Your authorized change will be applied and logged.':'BM or DM approval was granted. This permission applies once; your changes will be recorded.'}</p><button class="primary" type="submit">${['DM','BM','Admin'].includes(S.role)?'Save and record change':'Save approved edit'}</button></form>`);}
function syncDialog(id){const f=S.financials.find(x=>x.member_id===id);openModal('Sync actual document records',`<form onsubmit="event.preventDefault();handleCmsAction(this,'sync','${id}')"><div class="form-grid">${field('Active savings balance','savings',f?.savings||0,'number')}${field('Outstanding loan balance','loan_balance',f?.loan_balance||0,'number')}${field('Annual interest (%)','annual_interest',f?.annual_interest||0,'number')}<label>Loan status<select name="loan_status">${['No active loan','Active','Paid','Overdue','Restructured'].map(v=>`<option ${f?.loan_status===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('Record date','as_of',today(),'date')}<label>Record reference (optional)<input name="source_reference" maxlength="300" placeholder="Ledger number, statement date or form ID"><span class="hint">A label for the supporting record. Leave blank to use the attached filenames.</span></label><label class="full">Payment schedule<textarea name="schedule" placeholder="2026-11-15, 3200, Scheduled" rows="5">${(f?.schedule||[]).map(x=>`${x.date}, ${x.amount}, ${x.status||'Scheduled'}`).join('\n')}</textarea><span class="hint">One payment per line: YYYY-MM-DD, amount, status.</span></label><label class="full">Original supporting documents<input type="file" name="evidence" multiple required onchange="showSelectedDocuments(this)"><span class="hint">Select multiple scanned records, PDF, Word, Excel, images or other document files. Up to 10 files, 10 MB each, 50 MB total. Files stay private.</span><ul id="selectedDocuments" class="document-list"></ul></label><label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label></div><p class="smalltext">The member balance is updated only after a district manager and a different Admin approve this submission.</p><button type="submit" class="primary">Submit for DM review</button></form>`);}
function canReview(q){return q.submitted_by!==S.session.user.id&&(q.kind==='Profile edit'?q.status==='Pending'&&['DM','BM','Admin'].includes(S.role):(q.status==='Pending'&&S.role==='DM')||(q.status==='DM approved'&&S.role==='Admin'&&q.dm_reviewer!==S.session.user.id));}
function approvalsView(){return requestsView('Profile edit','Member edit approvals','Staff wait for BM or DM approval before editing. Approved permission can be used once.');}
function financialView(){return requestsView('Financial sync','Financial synchronization','Source documents → DM review → Admin approval → member account update.');}
function requestsView(kind,title,subtitle){const rows=scoped(S.requests).filter(q=>q.kind===kind);return heading(title,subtitle)+`<div class="request-grid">${rows.map(q=>`<section class="card"><div class="card-head"><div><h2>${e(S.profiles.find(p=>p.id===q.member_id)?.full_name||'Member')}</h2><p class="smalltext">${e(bn(q.branch_id))} · ${e(q.created_at.slice(0,10))}</p></div>${statusPill(q.status)}</div><p>${e(q.note)}</p>${button('View request',`requestDialog('${q.id}')`,'outline','file')}</section>`).join('')||empty('No requests yet','Submitted requests for your assigned branches appear here.')}</div>`;}
function requestDialog(id){const q=S.requests.find(q=>q.id===id);const v=q.proposed;openModal(q.kind,`<p>${e(q.note)}</p><dl class="details-list">${Object.entries(v).filter(([k])=>k!=='schedule'&&k!=='permission_only').map(([k,val])=>detail(e(k.replaceAll('_',' ')),e(val))).join('')}</dl>${q.kind==='Financial sync'?scheduleView(v.schedule):''}${documentList(q,id)}<p class="smalltext">${e(q.status)}${q.review_note?' · '+e(q.review_note):''}</p>${canReview(q)?`<form onsubmit="event.preventDefault();handleCmsAction(this,'review','${id}')"><label>Decision<select name="decision"><option>Approve</option><option>Reject</option></select></label><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><button class="primary" type="submit">Record decision</button></form>`:''}${q.status==='BM approved'&&q.submitted_by===S.session.user.id&&q.proposed.permission_only?button('Edit with approved permission',`editDialog('${q.member_id}','${id}')`,'primary','edit'):q.status==='BM approved'&&q.submitted_by===S.session.user.id?`<form onsubmit="event.preventDefault();handleCmsAction(this,'apply','${id}')"><button class="primary" type="submit">Apply approved changes</button></form>`:''}`);}
function requestDocuments(q){return q.evidence_files?.length?q.evidence_files:q.evidence_path?[{path:q.evidence_path,name:'Original source document'}]:[];}
function documentList(q,id){return requestDocuments(q).length?`<h3>Original supporting documents</h3><ul class="document-list">${requestDocuments(q).map((d,i)=>`<li>${button(d.name,`viewDocument('${id}',${i})`,'outline','file')}${d.size?`<small>${(d.size/1024/1024).toFixed(2)} MB</small>`:''}</li>`).join('')}</ul>`:'';}
function validateDocuments(files){if(!files.length||files.length>10)throw Error('Select 1 to 10 original supporting documents.');if(files.some(f=>!f.size||f.size>10*1024*1024))throw Error('Each document must contain data and be no larger than 10 MB.');if(files.reduce((n,f)=>n+f.size,0)>50*1024*1024)throw Error('The selected documents exceed 50 MB in total.');}
function showSelectedDocuments(input){const files=Array.from(input.files||[]);$('selectedDocuments').innerHTML=files.map(f=>`<li>${e(f.name)} <small>${(f.size/1024/1024).toFixed(2)} MB</small></li>`).join('');try{validateDocuments(files);input.setCustomValidity('');}catch(err){input.setCustomValidity(err.message);}}
async function viewDocument(id,index=0){const q=S.requests.find(q=>q.id===id),file=requestDocuments(q)[index];try{const url=await signedUrl('occci-documents',file.path);const a=document.createElement('a');a.href=url+(url.includes('?')?'&':'?')+'download='+encodeURIComponent(file.name);a.download=file.name;a.target='_blank';a.rel='noopener noreferrer';a.click();}catch(err){$('actionMessage').textContent=err.message;}}
function editPermissionDialog(id){const pending=S.requests.find(q=>q.member_id===id&&q.kind==='Profile edit'&&q.submitted_by===S.session.user.id&&['Pending','BM approved'].includes(q.status));if(pending)return requestDialog(pending.id);openModal('Request permission to edit',`<p>You can edit this member’s profile after a BM or DM approves your request. No profile information changes at this step.</p><form onsubmit="event.preventDefault();handleCmsAction(this,'editPermission','${id}')"><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required placeholder="Explain which information needs correction and why"></textarea></label><button type="submit" class="primary">Request BM / DM approval</button></form>`);}
function accountDialog(id){const p=S.profiles.find(p=>p.id===id);openModal('Assign / update ID number',`<form onsubmit="event.preventDefault();handleCmsAction(this,'account','${id}')"><label>Official ID / account number<input name="account" maxlength="40" value="${e(p.account_number||'')}" required></label><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><p class="hint">Use the official number verified by your branch. This records the ID without changing membership status.</p><button type="submit" class="primary">Save ID number</button></form>`);}
const auditFieldLabels={role:'Role',requested_role:'Requested position',membership_status:'Membership status',account_number:'Account number',full_name:'Complete name',first_name:'First name',last_name:'Last name',middle_name:'Middle name',contact_number:'Contact number',address:'Address',branch_id:'Branch',district:'District',savings:'Savings balance',loan_balance:'Loan balance',loan_status:'Loan status',annual_interest:'Annual interest',as_of:'Record date',source_reference:'Document reference',schedule:'Payment schedule',avatar:'Temporary avatar',photo_path:'Profile photo',evidence_path:'Source document',status:'Status',kind:'Type',title:'Title',body:'Content',published:'Publication',event_date:'Event date',decision:'Decision',active:'Branch status',archived_at:'Archived on',registration_kind:'Signup type',name:'Name',reason:'Reason / Comments / Notes'};
const auditInternalFields=new Set(['id','member_id','user_id','actor','request_id','revision','base_revision','created_at','updated_at','created_by','submitted_by','reviewed_at','reviewed_by','bm_reviewer','dm_reviewer','admin_reviewer']);
function auditFields(data,prefix=''){if(!data||typeof data!=='object'||Array.isArray(data))return [];return Object.entries(data).flatMap(([key,value])=>{if(auditInternalFields.has(key))return [];const path=prefix?prefix+'.'+key:key;if(value&&typeof value==='object'&&!Array.isArray(value))return auditFields(value,path);return [{path,key,label:path.split('.').map(k=>auditFieldLabels[k]||(k==='proposed'?'Proposed details':k.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase()))).join(' · '),value}];});}
function auditFormattedValue(key,value){if(value===null||value===undefined||value==='')return '<span class="audit-unset">Not set</span>';if(['savings','loan_balance','amount'].includes(key)&&Number.isFinite(Number(value)))return e(money(Number(value)));if(key==='annual_interest')return e(value)+'%';if(key==='branch_id')return e(S.branches.find(b=>b.id===value)?.name||'Branch no longer in directory');if(key==='district')return 'District '+e(value);if(['role','requested_role'].includes(key))return e(({Admin:'Admin',DM:'District Manager (DM)',BM:'Branch Manager (BM)',Staff:'Staff',Member:'Member'})[value]||value);if(key==='photo_path')return 'Photo on file';if(key==='evidence_path')return 'Source document on file';if(typeof value==='boolean')return key==='published'?(value?'Published':'Draft'):key==='active'?(value?'Active':'Inactive'):(value?'Yes':'No');if(key==='avatar')return e(defaultAvatars.find(([id])=>id===value)?.[1]||value);if(Array.isArray(value)){if(!value.length)return '<span class="audit-unset">No entries</span>';if(key==='schedule')return `<ul class="audit-schedule">${value.map(item=>`<li>${e(item.date||'Date not recorded')} · ${e(Number.isFinite(Number(item.amount))?money(Number(item.amount)):'Amount not recorded')}${item.status?' · '+e(item.status):''}</li>`).join('')}</ul>`;return `<ul class="audit-schedule">${value.map(item=>`<li>${item&&typeof item==='object'?auditFields(item).map(f=>e(f.label)+': '+auditFormattedValue(f.key,f.value)).join(' · '):e(item)}</li>`).join('')}</ul>`;}return e(value);}
function auditChangeDetails(entry){const previous=auditFields(entry.before_data),recorded=auditFields(entry.after_data),before=new Map(previous.map(f=>[f.path,f])),after=new Map(recorded.map(f=>[f.path,f]));const fields=recorded.length?recorded:previous;const changed=fields.filter(f=>!before.has(f.path)||!after.has(f.path)||JSON.stringify(before.get(f.path).value)!==JSON.stringify(after.get(f.path).value));if(!changed.length)return '<p class="hint">No additional field changes were recorded. See the action and reason above.</p>';return `<div class="audit-change-list">${changed.map(f=>`<section class="audit-change-row"><h4>${e(f.label)}</h4><div class="audit-change-values"><div><span class="audit-value-label">Previous</span><div>${before.has(f.path)?auditFormattedValue(f.key,before.get(f.path).value):'<span class="audit-unset">Not previously recorded</span>'}</div></div><div><span class="audit-value-label">Recorded</span><div>${after.has(f.path)?auditFormattedValue(f.key,after.get(f.path).value):'<span class="audit-unset">Not recorded in this action</span>'}</div></div></div></section>`).join('')}</div>`;}
function auditRows(rows){return rows.length?rows.map(a=>`<div class="notice"><span class="iconbox">${icon('clock')}</span><div class="notice-content"><h3>${e(a.action)}</h3><p>${e(a.note)}</p><small>${e(a.actor_name||S.profiles.find(p=>p.id===a.actor)?.full_name||(a.actor?'Cooperative user':'System'))}${a.actor_role?' · '+e(a.actor_role):''} · ${e(new Date(a.created_at).toLocaleString())}</small><details class="audit-details"><summary>View change details</summary>${auditChangeDetails(a)}</details></div></div>`).join(''):empty('No activity yet','Actions and approval decisions are recorded here.');}

function auditView(rows){return heading('Activity log',`Recorded changes, approvals and document synchronization. ${rows.length} accessible entries.`)+`<section class="card">${auditRows(rows)}</section>`;}
function contentView(cms,withHeading=true){const rows=S.content.filter(c=>(cms||c.published)&&(S.scope==='all'||c.branch_id===S.scope||!c.branch_id));return (withHeading?heading(cms?'Content management':'Cooperative updates',cms?'Manage announcements, events and services in your assigned scope.':'Updates from your cooperative.',cms&&['Admin','DM','BM'].includes(S.role)?button('Add content',"contentDialog('')",'primary','plus'):''):'<h2>Cooperative updates</h2>')+`<div class="request-grid">${rows.map(c=>`<article class="card"><span class="pill blue">${e(c.kind)}${c.published?'':' · Draft'}</span><h2 class="spacer">${e(c.title)}</h2><p class="content-body">${e(c.body)}</p>${c.event_date?`<p>${e(c.event_date)}</p>`:''}${cms&&['Admin','DM','BM'].includes(S.role)?button('Edit',`contentDialog('${c.id}')`,'outline','edit')+button('Delete',`removeDialog('Content','${c.id}')`,'danger'):''}</article>`).join('')||empty('No content published','The CMS will supply announcements, events and services.')}</div>`;}
function contentDialog(id){const c=S.content.find(c=>c.id===id)||{};openModal(id?'Edit content':'Create content',`<form onsubmit="event.preventDefault();handleCmsAction(this,'content','${id}')"><div class="form-grid"><label>Type<select name="kind">${['Announcement','Event','Service'].map(k=>`<option ${c.kind===k?'selected':''}>${k}</option>`).join('')}</select></label><label>Branch scope<select name="branch_id">${['Admin','DM'].includes(S.role)?'<option value="">'+(S.role==='Admin'?'All branches':'My district')+'</option>':''}${branchOptions(c.branch_id,false,true)}</select></label>${field('Title','title',c.title||'')}${field('Event date (optional)','event_date',c.event_date||'','date',false)}<label class="full">Content<textarea name="body" required>${e(c.body||'')}</textarea></label><label>Publication<select name="published"><option value="true" ${c.published!==false?'selected':''}>Published</option><option value="false" ${c.published===false?'selected':''}>Draft</option></select></label><label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label></div><button class="primary" type="submit">Save content</button></form>`);}
function branchesView(){const rows=S.role==='Admin'?S.branches:allowedBranches(),districts=[...new Set(rows.map(b=>b.district))].sort((a,b)=>a-b);if(!districts.includes(S.directoryDistrict))S.directoryDistrict=null;const selected=S.directoryDistrict;return heading(selected?'District '+selected+' branches':'Branch directory',selected?'Select a branch to view or manage its details.':'Select a district to view its branches.',(selected?button('All districts',"S.directoryDistrict=null;render()",'outline','location'):'')+(S.role==='Admin'?button('Add branch',"branchDialog('')",'primary','plus'):''))+`<div class="request-grid">${selected?rows.filter(b=>b.district===selected).map(b=>`<section class="card"><span class="iconbox">${icon('location')}</span><h2>OCCCI ${e(b.name)} Branch</h2><p>District ${b.district} · ${b.active?'Active':'Inactive'}</p>${S.role==='Admin'?button('Edit',`branchDialog('${e(b.id)}')`,'outline','edit')+button('Deactivate',`removeDialog('Branch','${e(b.id)}')`,'danger'):''}</section>`).join(''):districts.map(d=>`<section class="card district-card"><span class="iconbox">${icon('location')}</span><h2>District ${d}</h2><p>${rows.filter(b=>b.district===d).length} branches · ${rows.filter(b=>b.district===d&&b.active).length} active</p>${button('View branches',`S.directoryDistrict=${d};render()`,'primary','location')}</section>`).join('')||empty('No districts assigned','Your assigned branch directory will appear here.')}</div>`;}
function branchDialog(id){const b=S.branches.find(b=>b.id===id)||{};openModal('Branch details',`<form onsubmit="event.preventDefault();handleCmsAction(this,'branch','${e(id)}')"><div class="form-grid">${id?'':field('Internal branch reference','id')}${field('Branch name','name',b.name||'')}<label>District<select name="district">${[1,2,3,4,5,6].map(d=>`<option ${(b.district||S.directoryDistrict||1)===d?'selected':''}>${d}</option>`).join('')}</select></label><label class="full">Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label></div><button type="submit" class="primary">Save branch</button></form>`);}
function teamView(){return staffApplicationsView()+heading('Cooperative hierarchy','Admin → District Manager → Branch Manager → Staff → Member',S.role==='Admin'?button('Assign role',"teamDialog('')",'primary','plus'):'')+`<div class="request-grid">${S.team.map(t=>`<section class="card"><h2>${e(S.profiles.find(p=>p.id===t.user_id)?.full_name||t.user_id)}</h2><p>${e(t.role)} · ${t.role==='Admin'?'Cooperative':t.role==='DM'?'District '+t.district:e(bn(t.branch_id))}</p>${S.role==='Admin'?button('Edit',`teamDialog('${t.user_id}')`,'outline')+button('Remove assignment',`removeDialog('Team','${t.user_id}')`,'danger'):''}</section>`).join('')||empty('No team assignments','The initial Admin must be assigned through Supabase SQL Editor.')}</div>`;}
function staffApplicationsView(){if(S.role!=='Admin')return '';const rows=S.applications.filter(a=>a.status==='Pending');return heading('Staff applications',`${rows.length} awaiting review · Only Admin can grant DM, BM and Staff positions.`)+`<div class="request-grid spacer">${rows.map(a=>`<section class="card"><h2>${e(S.profiles.find(p=>p.id===a.user_id)?.full_name||'Applicant')}</h2><p>${e(a.requested_role)} · District ${a.district} · ${e(bn(a.branch_id))}</p>${statusPill(a.status)}${button('Review application',`staffApplicationDialog('${a.user_id}')`,'primary','shield')}</section>`).join('')||empty('No pending staff applications','New OCCCI Staff signups will appear here.')}</div>`;}
function staffApplicationDialog(id){const a=S.applications.find(a=>a.user_id===id),p=S.profiles.find(p=>p.id===id);openModal('Review OCCCI Staff application',`<dl class="details-list">${detail('Applicant',e(p?.full_name))}${detail('Position',e(a.requested_role))}${detail('District','District '+a.district)}${detail('Branch',e(bn(a.branch_id)))}${detail('Contact',e(p?.contact_number))}</dl><form onsubmit="event.preventDefault();handleCmsAction(this,'staffReview','${id}')"><label>Decision<select name="decision"><option>Approve</option><option>Reject</option></select></label><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><p class="smalltext">Approval grants this exact role and assignment. Email confirmation is required. Membership account approval is a separate process.</p><button type="submit" class="primary">Record staff decision</button></form>`);}
function teamDistrictOptions(selected){return [...new Set(S.branches.filter(b=>b.active).map(b=>b.district))].sort((a,b)=>a-b).map(d=>`<option value="${d}" ${Number(selected)===d?'selected':''}>District ${d}</option>`).join('');}
function teamBranchOptions(district,selected=''){const rows=S.branches.filter(b=>b.active&&b.district===Number(district));return `<option value="">${rows.length?'Select a branch':'No active branches in this district'}</option>`+rows.map(b=>`<option value="${e(b.id)}" ${b.id===selected?'selected':''}>OCCCI ${e(b.name)} Branch</option>`).join('');}
function teamDistrictChanged(){const branch=$('teamBranch');branch.innerHTML=teamBranchOptions($('teamDistrict').value,branch.value);}
function teamRoleChanged(){const role=$('teamRole').value,hasDistrict=role!=='Admin',hasBranch=['BM','Staff'].includes(role);$('teamDistrictField').hidden=!hasDistrict;$('teamDistrict').disabled=!hasDistrict;$('teamDistrict').required=hasDistrict;$('teamBranchField').hidden=!hasBranch;$('teamBranch').disabled=!hasBranch;$('teamBranch').required=hasBranch;if(hasBranch)teamDistrictChanged();$('teamScopeHint').textContent=role==='Admin'?'Admin covers every district and branch.':role==='DM'?'District Manager access covers all branches in the selected district.':'Access is limited to the selected branch in this district.';}
function teamAssignmentValues(values){const role=values.role;if(!['Admin','DM','BM','Staff'].includes(role))throw Error('Choose a valid role.');if(role==='Admin')return{role,branch_id:null,district:null};const district=Number(values.district);if(!S.branches.some(b=>b.active&&b.district===district))throw Error('Choose a district with active branches.');if(role==='DM')return{role,branch_id:null,district};const branch=S.branches.find(b=>b.active&&b.id===values.branch_id&&b.district===district);if(!branch)throw Error('Choose a branch in the selected district.');return{role,branch_id:branch.id,district:null};}
function teamDialog(id){const t=S.team.find(t=>t.user_id===id)||{},role=t.role||'Admin',district=t.district||S.branches.find(b=>b.id===t.branch_id)?.district||S.branches.find(b=>b.active)?.district;const labels={Admin:'Admin',DM:'District Manager (DM)',BM:'Branch Manager (BM)',Staff:'Staff'};openModal('Team assignment',`<form onsubmit="event.preventDefault();handleCmsAction(this,'team','${id}')"><label>Registered user<select name="user_id" ${id?'disabled':'required'}>${id?'':'<option value="">Select a registered user</option>'}${S.profiles.filter(p=>p.onboarding_complete!==false).map(p=>`<option value="${p.id}" ${p.id===id?'selected':''}>${e(p.full_name)} · ${e(p.account_number||p.id)}</option>`).join('')}</select></label>${id===S.session.user.id?'<p class="hint">You are editing your own access. Keep another Admin before changing your role.</p>':''}<label>Role<select id="teamRole" name="role" onchange="teamRoleChanged()">${['Admin','DM','BM','Staff'].map(r=>`<option value="${r}" ${role===r?'selected':''}>${labels[r]}</option>`).join('')}</select></label><p class="hint" id="teamScopeHint"></p><div class="form-grid team-scope-fields"><label id="teamDistrictField" ${role==='Admin'?'hidden':''}>District<select id="teamDistrict" name="district" onchange="teamDistrictChanged()" ${role==='Admin'?'disabled':'required'}>${teamDistrictOptions(district)}</select></label><label id="teamBranchField" ${['BM','Staff'].includes(role)?'':'hidden'}>Branch<select id="teamBranch" name="branch_id" ${['BM','Staff'].includes(role)?'required':'disabled'}>${teamBranchOptions(district,t.branch_id)}</select></label></div><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><button type="submit" class="primary">Save assignment</button></form>`);teamRoleChanged();}

function removeDialog(kind,id){const c=kind==='Content'?S.content.find(c=>c.id===id):null;openModal('Delete / archive '+kind,`<p>${kind==='Content'?'Content will be removed from publication.':kind==='Branch'?'This branch will be deactivated. Existing records stay attached to it.':kind==='Team'?'The user will return to member access.':'The member will be archived and removed from active lists.'} The action remains in the activity log.</p><form onsubmit="event.preventDefault();handleCmsAction(this,'remove','${id}','${kind}')"><label>Reason / Comments / Notes<textarea name="reason" minlength="3" required></textarea></label><button type="submit" class="danger">Confirm</button></form>`);}
function parseSchedule(text){return text.trim()?text.trim().split('\n').filter(Boolean).map(line=>{const [date,amount,status='Scheduled']=line.split(',').map(x=>x.trim());if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!amount||!Number.isFinite(Number(amount))||Number(amount)<0)throw Error('Check each schedule line: date, amount, status.');return{date,amount:Number(amount),status};}):[];}
async function handleCmsAction(form,kind,id,extra){const btn=form.querySelector('button[type=submit],button:not([type])');const buttonLabel=btn?.textContent;if(btn)btn.disabled=true;const f=new FormData(form),v=Object.fromEntries(f),reason=String(v.reason||'');try{
 if(kind==='staffReview')await rpc('occci_review_staff',{target:id,decision:v.decision,reason});
 if(kind==='membership')await rpc('occci_approve_member',{target:id,account:v.account,reason});
 if(kind==='account')await rpc('occci_assign_account',{target:id,account:v.account,reason});
 if(kind==='editPermission')await rpc('occci_submit_change',{target:id,request_kind:'Profile edit',values_json:{permission_only:true},evidence:null,reason});
 if(kind==='edit'){delete v.reason;if(S.role==='Staff')await rpc('occci_apply_authorized_edit',{request_id:extra,values_json:v,reason});else if(['DM','BM','Admin'].includes(S.role))await rpc('occci_manage_record',{record_kind:'Member',record_id:id,values_json:v,remove_record:false,reason});else throw Error('Member editing requires authorized cooperative access.');}
 if(kind==='sync'){const files=f.getAll('evidence').filter(file=>file?.size);validateDocuments(files);const schedule=parseSchedule(v.schedule),documents=[];for(const file of files){if(btn)btn.textContent=`Uploading ${documents.length+1} of ${files.length}…`;documents.push({path:await upload('occci-documents',file),name:file.name,size:file.size,type:file.type||'application/octet-stream'});}await rpc('occci_submit_financial_documents',{target:id,values_json:{savings:Number(v.savings),loan_balance:Number(v.loan_balance),loan_status:v.loan_status,annual_interest:Number(v.annual_interest),as_of:v.as_of,source_reference:v.source_reference.trim()||files.map(f=>f.name).join('; ').slice(0,300),schedule},documents,reason});}
 if(kind==='review')await rpc('occci_review_change',{request_id:id,decision:v.decision,reason});if(kind==='apply')await rpc('occci_apply_edit',{request_id:id});
 if(['content','branch','team','remove'].includes(kind)){let record_kind=kind==='remove'?extra:({content:'Content',branch:'Branch',team:'Team'})[kind],values_json=v;if(record_kind==='Content'){if(kind==='remove')values_json=S.content.find(c=>c.id===id);else values_json={...v,district:S.role==='DM'&&!v.branch_id?S.assignment.district:null,published:v.published==='true'};}if(record_kind==='Team'){values_json=kind==='remove'?{}:teamAssignmentValues(v);id=id||v.user_id;if(!id)throw Error('Select a registered user.');if(S.team.find(t=>t.user_id===id)?.role==='Admin'&&(kind==='remove'||values_json.role!=='Admin')&&!S.team.some(t=>t.role==='Admin'&&t.user_id!==id))throw Error('Keep at least one Admin. Assign another Admin before changing or removing this assignment.');}if(record_kind==='Branch')id=id||v.id;await rpc('occci_manage_record',{record_kind,record_id:id,values_json:values_json||{},remove_record:kind==='remove',reason});await loadBranches();}
 closeModal();await reload();if(!isStaff())S.page='Home';else if(!currentNav().some(([page])=>page===S.page))S.page='Overview';render();toast(S.error?'Saved, but refreshing failed. Use Retry to reload.':'Change saved and recorded.');}catch(err){const message=$('actionMessage');message.textContent=err.message;message.scrollIntoView?.({block:'nearest',behavior:'smooth'});}finally{if(btn){btn.disabled=false;btn.textContent=buttonLabel;}}}

async function loadActivity(){try{return await allRows('/rest/v1/rpc/occci_activity');}catch(err){if(!err.message.includes('Workflow database setup is pending'))throw err;return allRows('/rest/v1/occci_audit?select=*&order=created_at.desc,id.desc');}}
const OAUTH_KEY='occci.google.pkce.v1';
function base64url(bytes){return btoa(String.fromCharCode(...bytes)).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');}
async function googleSignIn(btn){btn.disabled=true;try{const settings=await api('/auth/v1/settings',{auth:false});if(!settings.external?.google)throw Error('Google sign-in is awaiting cooperative activation. Please use email sign-in for now.');
 const check=await fetch(C.url+'/rest/v1/occci_profiles?select=onboarding_complete&limit=0',{headers:{apikey:C.publishableKey},cache:'no-store'});const result=await check.json();if(!check.ok&&result.code!=='42501')throw Error('Google registration is awaiting cooperative setup. Please use email sign-in for now.');
 const verifier=base64url(crypto.getRandomValues(new Uint8Array(32))),challenge=base64url(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(verifier))));sessionStorage.setItem(OAUTH_KEY,JSON.stringify({verifier,created:Date.now()}));
 const url=new URL(C.url+'/auth/v1/authorize');url.search=new URLSearchParams({provider:'google',redirect_to:window.location.origin+'/',code_challenge:challenge,code_challenge_method:'s256'});window.location.assign(url.href);
 }catch(err){S.error=err.message;render();}finally{btn.disabled=false;}}
async function finishGoogleSignIn(){const url=new URL(window.location.href),code=url.searchParams.get('code'),error=url.searchParams.get('error_description')||url.searchParams.get('error');if(!code&&!error)return;let flow;try{flow=JSON.parse(sessionStorage.getItem(OAUTH_KEY)||'null');}catch{}sessionStorage.removeItem(OAUTH_KEY);for(const key of ['code','error','error_description','error_code'])url.searchParams.delete(key);window.history.replaceState(null,'',url.pathname+url.search+url.hash);
 if(error)throw Error('Google sign-in was not completed. Please try again.');if(!flow?.verifier||Date.now()-flow.created>10*60*1000)throw Error('Google sign-in expired or opened in a different browser. Start again on this device.');
 const result=await api('/auth/v1/token?grant_type=pkce',{method:'POST',auth:false,data:{auth_code:code,code_verifier:flow.verifier}});storeSession({...result,expires_at:Date.now()/1000+result.expires_in});S.page='Home';}
function onboardingView(){const originalMode=S.authMode;S.authMode='register';let html=authView();S.authMode=originalMode;const start=html.indexOf('<form onsubmit='),end=html.indexOf('<p class="smalltext">',start);html=html.slice(start,end).replace('submitAuth(this)','completeOnboarding(this)');html=html.slice(0,html.indexOf('<label>Email'))+'</div><p class="smalltext">Your Google email is verified. Cooperative membership and staff access still require approval.</p><button type="submit" class="primary">Save and continue</button><p id="authMessage" role="status" aria-live="polite"></p></form>';return heading('Complete your profile','Choose your district and branch, enter your details, and select an avatar.')+'<section class="card auth-card">'+html+'</section>';}
async function completeOnboarding(form){const btn=form.querySelector('[type=submit]');btn.disabled=true;try{const f=new FormData(form),data=Object.fromEntries(f);delete data.photo;await rpc('occci_complete_onboarding',{values_json:data});await reload();if(isStaff())S.page='Overview';render();const file=f.get('photo');if(file?.size){try{await uploadPhotoBlob(await normalizePhoto(file));}catch(err){toast('Profile saved. '+err.message);}}}catch(err){const node=$('authMessage');if(node)node.textContent=err.message;else toast(err.message);}finally{btn.disabled=false;}}

async function init(){try{const s=JSON.parse(localStorage.getItem(SESSION_KEY)||'null');if(s?.access_token&&s?.refresh_token)S.session=s;}catch{}try{await loadBranches();await finishGoogleSignIn();}catch(err){S.error=err.message;}if(S.session)await reload();else render();if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});}
init();
